const body = $json.body ?? $json;
const pergunta = String(body.pergunta ?? body.message ?? body.chatInput ?? '').trim();
if (!pergunta) throw new Error('Envie a pergunta no campo pergunta, message ou chatInput.');
const sessionId = String(body.session_id ?? body.sessionId ?? body.user_id ?? body.userId ?? `sessao-${Date.now()}`).trim();
const modeRaw = String(body.mode || 'answer').toLowerCase();
const mode = ['plan', 'answer', 'rule'].includes(modeRaw) ? modeRaw : 'answer';
const allowed = ['value', 'definition', 'formula', 'average', 'median', 'comparison', 'location', 'quality', 'mixed', 'clarification', 'general', 'rule'];
const intent = allowed.includes(body.intent) ? body.intent : (mode === 'rule' ? 'formula' : 'general');
const queryPlan = (body.query_plan && typeof body.query_plan === 'object') ? body.query_plan : null;
const queryResult = (body.query_result && typeof body.query_result === 'object') ? body.query_result : null;
const resolvedMetric = (body.resolved_metric && typeof body.resolved_metric === 'object') ? body.resolved_metric : null;
const portalContext = (body.portal_context && typeof body.portal_context === 'object')
  ? body.portal_context
  : (body.current_page ? { current_page: body.current_page } : null);
const conversationContext = (body.conversation_context && typeof body.conversation_context === 'object')
  ? {
      last_domain: body.conversation_context.last_domain ?? null,
      last_metric: body.conversation_context.last_metric ?? null,
      last_filters: body.conversation_context.last_filters || {},
      last_intent: body.conversation_context.last_intent ?? null,
      last_aggregation: body.conversation_context.last_aggregation ?? null,
      current_page: body.conversation_context.current_page ?? portalContext?.current_page ?? null,
    }
  : { last_domain: null, last_metric: null, last_filters: {}, last_intent: null, last_aggregation: null, current_page: portalContext?.current_page ?? null };
const metricRule = typeof body.metric_rule === 'string' ? body.metric_rule : null;
return [{ json: {
  mode,
  pergunta,
  session_id: sessionId,
  sessionId,
  intent,
  query_plan: queryPlan,
  query_result: queryResult,
  resolved_metric: resolvedMetric,
  portal_context: portalContext,
  current_page: portalContext?.current_page ?? body.current_page ?? null,
  conversation_context: conversationContext,
  metric_rule: metricRule,
  usuario: { nome: body.user_name ?? body.userName ?? null, email: body.user_email ?? body.userEmail ?? null },
  origem: body.origem ?? 'portal-analytics-jornada',
  recebido_em: new Date().toISOString()
} }];

const original = $('Validar e Normalizar Entrada').item.json;
const agent = $json;
const mode = original.mode || 'answer';
const rawAnswer = agent.output ?? agent.text ?? agent.response ?? '';
if (mode === 'plan') {
  let parsed = null;
  const text = String(rawAnswer || '');
  const m = text.match(/\{[\s\S]*\}/);
  if (m) { try { parsed = JSON.parse(m[0]); } catch (e) { parsed = null; } }
  if (!parsed || typeof parsed !== 'object') {
    return [{ json: { success: true, mode: 'plan', session_id: original.session_id ?? original.sessionId, query_plan: null, clarification: 'Não foi possível interpretar a consulta. Reformule a pergunta.', conversation_context: original.conversation_context || null, generated_at: new Date().toISOString() } }];
  }
  const plan = parsed.query_plan || (parsed.domain || parsed.metric ? parsed : null);
  return [{ json: { success: true, mode: 'plan', session_id: original.session_id ?? original.sessionId, query_plan: plan, clarification: parsed.clarification ?? null, conversation_context: original.conversation_context || null, generated_at: new Date().toISOString() } }];
}
let answer = String(rawAnswer || 'Não foi possível gerar uma resposta.').trim();
const qp = original.query_plan || {};
const qr = original.query_result || {};
const intent = original.intent || qp.intent || 'general';
const sources = Array.isArray(qr.sources) ? qr.sources : [];
const warnings = Array.isArray(qr.warnings) ? qr.warnings : [];
const filterLabels = Array.isArray(qr.filter_labels) ? qr.filter_labels : [];
const realtime = !!(qr && qr.realtime_database === true);
const onlyNumber = /^\s*[\d.,]+\s*%?\s*$/.test(answer);
if ((intent === 'formula' || intent === 'definition' || intent === 'location' || mode === 'rule') && onlyNumber) {
  const fallback = qr.definition_text || qr.location_text || original.metric_rule || 'Consulte a regra do indicador no catálogo do portal.';
  return [{ json: { success: true, mode, session_id: original.session_id ?? original.sessionId, answer: fallback, intent, domain: qp.domain ?? qr.domain ?? null, metric: qp.metric ?? qr.metric ?? null, aggregation: qp.aggregation ?? qr.aggregation ?? null, value: null, sources, warnings, filter_labels: filterLabels, conversation_context: original.conversation_context || null, realtime_database: false, generated_at: new Date().toISOString() } }];
}
if (qr && qr.value != null && typeof qr.value === 'number') {
  const variants = [String(qr.value), Number(qr.value).toLocaleString('pt-BR'), Number(qr.value).toLocaleString('pt-BR', { maximumFractionDigits: 2 })];
  const hasOfficial = variants.some((v) => answer.includes(v));
  const approx = /\b(aproximadamente|cerca de|quase|em torno de|por volta de|mais ou menos)\b/i.test(answer);
  if (approx || !hasOfficial) {
    const unit = qr.unit === 'clients' ? 'clientes' : qr.unit === 'percent' ? '%' : qr.unit === 'days' ? 'dias' : (qr.unit || '');
    answer = `Temos ${qr.value} ${unit}`.trim() + '.';
  }
}
return [{ json: { success: true, mode, session_id: original.session_id ?? original.sessionId, answer, intent, domain: qp.domain ?? qr.domain ?? null, metric: qp.metric ?? qr.metric ?? null, aggregation: qp.aggregation ?? qr.aggregation ?? null, value: qr.value ?? null, value_detail: qr.value_detail ?? null, sample_size: qr.sample_size ?? null, unit: qr.unit ?? null, filters: qr.filters ?? qp.filters ?? null, filter_labels: filterLabels, sources, warnings, conversation_context: original.conversation_context || null, realtime_database: realtime, generated_at: new Date().toISOString() } }];
